    path: "tmp_verify_asset_model_ellipsis.cjs",
    content: "const fs = require('fs');\nconst file = 'apps/web-ele/src/views/finance/assets/manage/list/index.vue';\nconst s = fs.readFileSync(file, 'utf8');\nconst checks = [\n  ['model cell class', 'class=\"asset-model-cell\"'],\n  ['model title', ':title=\"String(row.model || \\'\\')\"'],\n  ['ellipsis overflow', 'text-overflow: ellipsis;'],\n  ['nowrap', 'white-space: nowrap;'],\n];\nfor (const [name, text] of checks) {\n  if (!s.includes(text)) throw new Error(`missing ${name}`);\n  console.log('ok', name);\n}\n",
