    content: "const fs=require('fs');\nconst p='apps/web-ele/src/views/finance/ledger/chronological/index.vue';\nconst s=fs.readFileSync(p,'utf8');\nconst checks=[\n  ['imports ExcelJS', s.includes(\"import ExcelJS from 'exceljs';\")],\n  ['uses account set store', s.includes('useAccountSetStore') && s.includes('getAccountSetNameForFile')],\n  ['export loading state', s.includes('exportLoading') && s.includes(':loading=\"exportLoading\"')],\n  ['xlsx export function', s.includes('async function exportCurrent()') && s.includes(\"workbook.addWorksheet('序时账')\")],\n  ['title merge A1:J1', s.includes(\"sheet.mergeCells('A1:J1')\")],\n  ['meta row merges', s.includes(\"sheet.mergeCells('A2:D2')\") && s.includes(\"sheet.mergeCells('E2:H2')\") && s.includes(\"sheet.mergeCells('I2:J2')\" )],\n  ['sample headers', s.includes(\"'日期', '凭证字号', '摘要', '科目编码', '科目名称', '借方金额', '贷方金额', '制单人', '审核人', '来源'\")],\n  ['total row', s.includes(\"sheet.addRow(['合计'\") && s.includes('totalDebit') && s.includes('totalCredit')],\n  ['xlsx file name', s.includes(\"a.download = '序时账_\") && s.includes(\".xlsx'\")],\n  ['no csv export button', !s.includes('@click=\"exportCsv\"')],\n];\nfor (const [name, ok] of checks) console.log(name + ': ' + (ok ? 'OK' : 'FAIL'));\nif (checks.some(([, ok]) => !ok)) process.exit(1);\n",
