    path: "tmp_verify_currency_sfc.cjs",
    content: "const fs=require('fs');\nconst path=require('path');\nconst { parse, compileTemplate } = require('@vue/compiler-sfc');\nconst files=['apps/web-ele/src/views/finance/settings/currency/index.vue'];\nfor(const file of files){\n  const source=fs.readFileSync(file,'utf8');\n  const parsed=parse(source,{filename:file});\n  if(parsed.errors && parsed.errors.length){\n    console.error('parse errors', parsed.errors);\n    process.exit(1);\n  }\n  const descriptor=parsed.descriptor;\n  const result=compileTemplate({\n    source: descriptor.template.content,\n    filename:file,\n    id:'currency-sfc-verify',\n    compilerOptions:{mode:'module'},\n  });\n  if(result.errors && result.errors.length){\n    console.error('template errors', result.errors);\n    process.exit(1);\n  }\n  console.log(`${file}: SFC parse ok, template compile ok`);\n}\n",
