function listVerifies() {
  return VERIFY_SOURCES.map((item, index) => ({ index: index + 1, path: item.path, bytes: Buffer.byteLength(item.content, 'utf8') }));
}

function extractVerifies(targetDir = 'tmp_verify_extracted') {
  const fs = require('fs');
  const path = require('path');
  for (const item of VERIFY_SOURCES) {
    const file = path.join(targetDir, item.path);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, item.content, 'utf8');
  }
  return VERIFY_SOURCES.length;
}

if (require.main === module) {
  const cmd = process.argv[2] || 'list';
  if (cmd === 'extract') {
    const count = extractVerifies(process.argv[3] || 'tmp_verify_extracted');
    console.log(`extracted ${count} verify scripts`);
  } else {
    console.log(JSON.stringify({ count: VERIFY_SOURCES.length, verifies: listVerifies() }, null, 2));
  }
}

module.exports = { VERIFY_SOURCES, listVerifies, extractVerifies };
